import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';

const source = fs.readFileSync('/tmp/uos-ecology-refresh.js', 'utf8');
const settle = async () => { for (let n = 0; n < 12; n++) await Promise.resolve(); };
function setup() {
  let tick = 0, clock = 10000, requests = 0, onHide;
  const timers = new Map();
  const nodes = new Map(['ecology-refresh-status', 'ecology-cycle', 'ecology-participants',
    'ecology-invocations', 'ecology-receipts-json', 'ecology-participant-rows'].map(id => [id, {
    textContent: '', dataset: {}, replaceChildren(...rows) { this.rows = rows; }
  }]));
  let respond = async () => ({ok: true, body: {getReader() {
    let done = false;
    return {async read() { if (done) return {done: true}; done = true;
      return {done: false, value: new TextEncoder().encode(JSON.stringify({cycle_counter: 4,
        total_holons: 1, invocation_sequence: 7,
        holons: [{id: '<img onerror=bad()>', mode: 'homeostatic', active_capabilities: 3,
          successful_invocations: 2, last_outcome: 'engaged'}]}))}; }, releaseLock() {}, async cancel() {}};
  }}});
  class ClockDate extends Date { constructor(value = clock) { super(value); } static now() { return clock; } }
  const context = {
    document: {hidden: false, getElementById: id => nodes.get(id), createElement: tag => ({tag, textContent: '', cells: [], appendChild(child) { this.cells.push(child); }})},
    window: {addEventListener(_name, callback) { onHide = callback; }},
    setTimeout: (callback, delay) => { const id = ++tick; timers.set(id, {callback, delay}); return id; },
    clearTimeout: id => timers.delete(id),
    fetch: (_path, options) => { requests++; assert.equal(options.method, 'GET'); return respond(options); },
    Date: ClockDate, TextDecoder, AbortController
  };
  vm.runInNewContext(source, context);
  const runTimer = delay => { const match = [...timers].find(([, timer]) => timer.delay === delay);
    assert.ok(match, 'expected timer ' + delay); timers.delete(match[0]); match[1].callback(); };
  return {nodes, timers, context, runTimer, requests: () => requests,
    clock: value => { clock = value; }, respond: value => { respond = value; }, hide: () => onHide()};
}

const state = setup();
await settle();
assert.equal(state.nodes.get('ecology-cycle').textContent, '4');
assert.equal(state.nodes.get('ecology-participants').textContent, '1');
assert.equal(state.nodes.get('ecology-invocations').textContent, '7');
assert.equal(state.nodes.get('ecology-refresh-status').dataset.state, 'live');
assert.equal(state.nodes.get('ecology-participant-rows').rows[0].cells[0].textContent, '<img onerror=bad()>');
assert.equal(state.timers.size, 1);
console.log('PASS live counters, participant rows use literal text, one scheduled next read');

state.clock(16001); state.runTimer(2000); await settle();
assert.equal(state.nodes.get('ecology-refresh-status').dataset.state, 'stale');
console.log('PASS non-advancing cycle becomes visibly stale');

state.respond(async () => ({ok: false, status: 503}));
state.runTimer(2000); await settle();
assert.equal(state.nodes.get('ecology-refresh-status').dataset.state, 'error');
assert.equal(state.nodes.get('ecology-cycle').textContent, '4');
console.log('PASS HTTP failure retains the last snapshot and announces error');

state.respond(({signal}) => new Promise((_resolve, reject) => signal.addEventListener('abort', () => reject(Object.assign(new Error('aborted'), {name: 'AbortError'})))));
state.runTimer(2000); await settle();
assert.equal(state.timers.size, 1);
assert.equal([...state.timers.values()][0].delay, 1500);
state.runTimer(1500); await settle();
assert.match(state.nodes.get('ecology-refresh-status').textContent, /read timed out/);
assert.equal(state.timers.size, 1);
console.log('PASS deadline aborts a stalled request before scheduling another');

let cancelled = false;
state.respond(async () => ({ok: true, body: {getReader: () => ({
  async read() { return {done: false, value: new Uint8Array(1048577)}; },
  async cancel() { cancelled = true; }, releaseLock() {}
})}}));
state.runTimer(2000); await settle();
assert.ok(cancelled);
assert.match(state.nodes.get('ecology-refresh-status').textContent, /snapshot exceeds limit/);
console.log('PASS oversized response is cancelled without replacing the snapshot');

const beforeHidden = state.requests();
state.context.document.hidden = true; state.runTimer(2000); await settle();
assert.equal(state.requests(), beforeHidden);
assert.equal(state.nodes.get('ecology-refresh-status').dataset.state, 'paused');
state.hide();
assert.equal(state.timers.size, 0);
console.log('PASS hidden page pauses reads and page exit removes its timer');

